class CombatSystem {
  constructor() { this.now = 0; this.status = {}; }
  applyStatus(target, effect, duration) { if (!this.status[target]) this.status[target] = {}; this.status[target][effect] = duration; }
  getEffect(target, effect) { return this.status[target]?.[effect] ?? 0; }
  advance(dt) {
    this.now += dt;
    for (const t in this.status) for (const e in this.status[t]) this.status[t][e] = Math.max(0, this.status[t][e] - dt);
  }
}

class Combat {
  constructor(combat, p1, p2) {
    this.combat = combat;
    this.p1 = p1; this.p2 = p2;
    this.order = []; this.log = [];
  }
  log(msg) { this.log.push('[' + this.combat.now.toFixed(2) + '] ' + msg); }
  report() { return this.log.join('\n'); }
  attack(attacker, defender) {
    const dmg = Math.max(1, attacker.attack - defender.defense);
    defender.hp -= dmg;
    this.log(`${attacker.name} hits ${defender.name} for ${dmg}`);
    if (defender.hp <= 0) this.log(`${defender.name} is defeated!`);
  }
  round() {
    this.order = [this.p1, this.p2].sort((a, b) => b.speed - a.speed);
    for (const a of this.order) {
      if (this.p1.hp <= 0 || this.p2.hp <= 0) break;
      if (this.combat.getEffect(a.name, 'stun') > 0) { this.log(`${a.name} is stunned and skips their turn`); continue; }
      this.attack(a, a === this.p1 ? this.p2 : this.p1);
    }
    this.combat.advance(1);
  }
}

// --- self-checking demo ---
const combat = new CombatSystem();
const hero = { name: 'Hero', hp: 100, attack: 10, defense: 2, speed: 8 };
const foe = { name: 'Foe', hp: 80, attack: 6, defense: 3, speed: 7 };
const match = new Combat(combat, hero, foe);

match.round();                             // hero strikes first
assert(hero.hp === 100 && foe.hp < 80, 'hero deals damage');
const hp1 = foe.hp;

for (let i = 0; i < 4; i++) match.round(); // foe builds up poison on hero
combat.applyStatus(hero.name, 'poison', 5);
assert(match.getEffect(hero.name, 'poison') > 0, 'poison applied');
for (let i = 0; i < 5; i++) match.round(); // poison ticks to zero during foe's turns
assert(match.getEffect(hero.name, 'poison') === 0, 'poison wears off');
assert(hero.hp < hp1, 'poison dealt damage');

combat.applyStatus(hero.name, 'stun', 1);   // stun blocks the hero's next turn
match.round();
assert(hero.hp === hp1, 'stunned hero takes no action');
assert(foe.hp < hp1, 'but foe still attacks');

while (foe.hp > 0) match.round();          // foe kills hero
assert(hero.hp <= 0, 'hero defeated');
console.log('gen combat fantasy/poison OK');
