// A* Pathfinding Algorithm Implementation

class PriorityQueue {
  constructor() {
    this.elements = [];
  }

  // Add an element to the queue
  enqueue(element, priority) {
    this.elements.push({ element, priority });
    this.elements.sort((a, b) => a.priority - b.priority);
  }

  // Remove and return the element with the highest priority
  dequeue() {
    if (this.isEmpty()) {
      throw new Error("Queue is empty");
    }
    return this.elements.shift().element;
  }

  // Check if the queue is empty
  isEmpty() {
    return this.elements.length === 0;
  }

  // Get the size of the queue
  size() {
    return this.elements.length;
  }
}

class Grid {
  constructor(rows, cols) {
    this.rows = rows;
    this.cols = cols;
    this.grid = Array.from({ length: rows }, () =>
      Array(cols).fill(false)
    );
  }

  // Set a cell as an obstacle
  setObstacle(row, col) {
    if (row >= 0 && row < this.rows && col >= 0 && col < this.cols) {
      this.grid[row][col] = true;
    }
  }

  // Check if a cell is an obstacle
  isObstacle(row, col) {
    return (
      row < 0 ||
      row >= this.rows ||
      col < 0 ||
      col >= this.cols ||
      this.grid[row][col]
    );
  }

  // Get the neighbors of a cell
  getNeighbors(row, col) {
    const directions = [
      [-1, 0], // Up
      [1, 0],  // Down
      [0, -1], // Left
      [0, 1],  // Right
    ];

    const neighbors = [];
    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (!this.isObstacle(newRow, newCol)) {
        neighbors.push([newRow, newCol]);
      }
    }

    return neighbors;
  }
}

function heuristic(a, b) {
  // Manhattan distance
  return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
}

function aStar(grid, start, goal) {
  const openSet = new PriorityQueue();
  const cameFrom = {};
  const gScore = {};
  const fScore = {};

  openSet.enqueue(start, 0);
  gScore[start] = 0;
  fScore[start] = heuristic(start, goal);

  while (!openSet.isEmpty()) {
    const current = openSet.dequeue();

    if (current[0] === goal[0] && current[1] === goal[1]) {
      return reconstructPath(cameFrom, current);
    }

    for (const neighbor of grid.getNeighbors(current[0], current[1])) {
      const tentativeGScore = gScore[current] + 1;

      if (!gScore[neighbor] || tentativeGScore < gScore[neighbor]) {
        cameFrom[neighbor] = current;
        gScore[neighbor] = tentativeGScore;
        fScore[neighbor] = tentativeGScore + heuristic(neighbor, goal);
        openSet.enqueue(neighbor, fScore[neighbor]);
      }
    }
  }

  return null; // No path found
}

function reconstructPath(cameFrom, current) {
  const totalPath = [current];
  while (cameFrom[current]) {
    current = cameFrom[current];
    totalPath.unshift(current);
  }
  return totalPath;
}

// Demo
const rows = 10;
const cols = 10;
const grid = new Grid(rows, cols);

// Set some obstacles
grid.setObstacle(2, 2);
grid.setObstacle(2, 3);
grid.setObstacle(3, 2);
grid.setObstacle(3, 3);
grid.setObstacle(4, 4);
grid.setObstacle(5, 4);
grid.setObstacle(6, 4);

const start = [0, 0];
const goal = [9, 9];

const path = aStar(grid, start, goal);

console.log("Grid:");
for (let i = 0; i < rows; i++) {
  let rowStr = "";
  for (let j = 0; j < cols; j++) {
    if (grid.isObstacle(i, j)) {
      rowStr += "# ";
    } else if (path && path.some(([r, c]) => r === i && c === j)) {
      rowStr += ". ";
    } else {
      rowStr += "  ";
    }
  }
  console.log(rowStr);
}

console.log("\nPath:", path);
