class Economy {
  constructor(base) { this.base = base; this.stock = new Map(); }
  setStock(id, units) { this.stock.set(id, units); }
  price(id) {
    const base = this.base[id] || 1;
    const stock = this.stock.get(id) || 0;
    return Math.round(base * (1 + Math.sin(stock / 5))); // oscillating price
  }
  buy(id, qty) {
    const cost = this.price(id) * qty;
    if (this.stock.get(id) < qty) return { ok: false, cost };
    this.stock.set(id, this.stock.get(id) - qty);
    return { ok: true, cost };
  }
}

class Inventory {
  constructor() { this.goods = new Map(); }
  add(id, qty) {
    this.goods.set(id, (this.goods.get(id) || 0) + qty);
  }
  has(id, qty) {
    return (this.goods.get(id) || 0) >= qty;
  }
}

class Store {
  constructor(economy, inventory) { this.economy = economy; this.inv = inventory; }
  purchase(id, qty) {
    const result = this.economy.buy(id, qty);
    if (result.ok) this.inv.add(id, qty);
    return result;
  }
}

// --- self-checking demo ---
const econ = new Economy({ apple: 10, banana: 5 });
econ.setStock('apple', 20);
econ.setStock('banana', 10);

