class Example extends Phaser.Scene
{
    time = 0;
    bullets;
    moveKeys;
    reticle;
    player;

    preload ()
    {
        // this.load.setBaseURL('https://cdn.phaserfiles.com/v385');
        // Load in images and sprites
        this.load.spritesheet('player_handgun', 'assets/sprites/player_handgun.png',
            { frameWidth: 66, frameHeight: 60 }
        ); // Made by tokkatrain: https://tokkatrain.itch.io/top-down-basic-set
        this.load.image('target', 'assets/demoscene/ball.png');
        this.load.image('background', 'assets/skies/underwater1.png');
    }

    create ()
    {
        // Set world bounds
        this.physics.world.setBounds(0, 0, 1600, 1200);

        // Add background, player, and reticle sprites
        const background = this.add.image(800, 600, 'background');
        this.player = this.physics.add.sprite(800, 600, 'player_handgun');
        this.reticle = this.physics.add.sprite(800, 700, 'target');

        // Set image/sprite properties
        background.setOrigin(0.5, 0.5).setDisplaySize(1600, 1200);
        this.player.setOrigin(0.5, 0.5).setDisplaySize(132, 120).setCollideWorldBounds(true);
        this.reticle.setOrigin(0.5, 0.5).setDisplaySize(25, 25).setCollideWorldBounds(true);

        // Set camera zoom
        this.cameras.main.zoom = 0.5;

        // Creates object for input with WASD kets
        this.moveKeys = this.input.keyboard.addKeys({
            up: Phaser.Input.Keyboard.KeyCodes.W,
            down: Phaser.Input.Keyboard.KeyCodes.S,
            left: Phaser.Input.Keyboard.KeyCodes.A,
            right: Phaser.Input.Keyboard.KeyCodes.D
        });

        // Enables movement of player with WASD keys
        this.input.keyboard.on('keydown_W', event => {
            this.player.body.velocity.y = -400;
        });
        this.input.keyboard.on('keydown_S', event => {
            this.player.body.velocity.y = 400;
        });
        this.input.keyboard.on('keydown_A', event => {
            this.player.body.velocity.x = -400;
        });
        this.input.keyboard.on('keydown_D', event => {
            this.player.body.velocity.x = 400;
        });

        // Stops player from moving when opposite key is pressed
        this.input.keyboard.on('keydown_A', event => {
            if (this.moveKeys.left.isDown && this.moveKeys.down.isDown)
            { this.player.body.velocity.y = 0; }
            else if (this.moveKeys.left.isDown && this.moveKeys.up.isDown)
            { this.player.body.velocity.y = 0; }
        });
        this.input.keyboard.on('keydown_D', event => {
