class StateMachine:
    var states = {}
    var current_state = null

    func add_state(name, state):
        states[name] = state

    func set_current(name):
        current_state = name
        states[name].enter()

    func transition_to(name):
        if not states.has(name):
            return false
        if current_state != null:
            states[current_state].exit()
        current_state = name
        states[name].enter()
        return true

    func update(delta):
        if current_state != null:
            states[current_state].update(delta)

