class Map{constructor(rows,cols){this.rows=rows;this.cols=cols;this.grid=Array.from({length:rows},()=>Array(cols).fill('.'));}set(x,y,value){this.grid[y][x]=value;}get(x,y){return this.grid[y]?.[x]||'#';}neighbours(x,y){return [{dx:-1,dy:0},{dx:1,dy:0},{dx:0,dy:-1},{dx:0,dy:1}].map(({dx,dy})=>({x:x+dx,y:y+dy,value:this.get(x+dx,y+dy)})).filter((a)=>a.value!=='#');}}
const m=new Map(3,4);for(let x=0;x<4;x++)m.set(x,0,'#');m.set(1,1,'*');assert(m.neighbours(1,1).length===2,'doors on the wall');const open={0:'.',1:'.'};m.set(0,1,'|');m.set(2,1,'|');assert(m.neighbours(1,1).length===4,'open door reaches neighbours');console.log('ok');
