// Interpreting: "dumb enemies" (light ask) most usefully means basic chase AI that loses interest once an enemy is "far enough away" — chase when near, ignore when far.
class EnemyAI{constructor(x){this.x=x;}update(playerX){const d=playerX-this.x;if(Math.abs(d)<=8)this.x+=Math.sign(d);return this.x;}}
const e=new EnemyAI(0);e.update(7);assert(e.x===1,'chases when near');for(let i=0;i<100;i++)e.update(58);assert(Math.abs(e.x-58)>8,'loses interest when far');console.log('ok');
